//! Crystal: the `azul` shard (generated by `doc/src/codegen/v2/lang_crystal`,
//! `require "azul"`).
//!
//! Spellings: every class wraps its C type (`Azul::CssProperty`), static
//! functions are snake_case class methods of the C method name with
//! `create` -> `new` and `create_x` -> `x` (`Azul::CssProperty.text_color(..)`,
//! `Azul::FloatValue.new(1.0_f32)`), a variant constructor likewise
//! (`Azul::LayoutWidth.px(..)`, `Azul::LayoutWidth.auto`); C-like enums are
//! `Azul::LayoutDisplay::Flex`; a `CssPropertyValue<T>` alias / a
//! `CssProperty` variant without a constructor is its variant class
//! (`Azul::LayoutWidthValue::Exact.new(..)`, `Azul::CssProperty::Width.new(..)`);
//! a Vec parameter takes any `Enumerable` (an array literal
//! `[..] of Azul::X`), a String parameter a Crystal `String`.
//!
//! A struct without a field constructor is its lib struct wrapped:
//! `Azul::StyleTextColor.__own(LibAzul::AzStyleTextColor.new(inner: ..))`,
//! the fields as raw C values (a wrapper's `.__take`, a nested struct's lib
//! struct, `Azul::Conv.in_<Vec>([..])`, `Azul::Native.az_string("..")`).
//! A style returns its properties as an `Array(Azul::CssPropertyWithConditions)`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{
        escape_quoted, expr_doc, is_tall, item_comments, item_doc, native_list, unicode_braced,
        variant_ctor_method, ExprSyntax,
    },
    CodegenBackend, GeneratedFile,
};

/// The Crystal printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Crystal;

/// `is_crystal_keyword` of `lang_crystal/mod.rs` (lib struct field names).
const KEYWORDS: &[&str] = &[
    "abstract", "alias", "as", "asm", "begin", "break", "case", "class", "def", "do", "else",
    "elsif", "end", "ensure", "enum", "extend", "false", "for", "fun", "if", "in", "include",
    "instance_sizeof", "lib", "macro", "module", "next", "nil", "of", "offsetof", "out",
    "pointerof", "private", "protected", "require", "rescue", "return", "select", "self",
    "sizeof", "struct", "super", "then", "true", "type", "typeof", "uninitialized", "union",
    "unless", "until", "when", "while", "with", "yield",
];

/// `reserved_method` of `lang_crystal/wrappers.rs`.
const RESERVED_METHODS: &[&str] = &[
    "as", "as?", "is_a?", "nil?", "responds_to?", "class", "hash", "clone", "dup", "to_s",
    "inspect", "to_unsafe", "finalize", "initialize", "allocate", "object_id", "same?",
    "not_nil!", "try", "tap", "itself", "crystal_type_id", "unsafe_as", "in?", "default",
    "pretty_print",
];

/// `snake` of `lang_crystal/wrappers.rs`: `_` before every capital.
fn snake(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i != 0 && !out.ends_with('_') {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// The class-method name of the C method `c_method` (`method_name` of
/// `lang_crystal/wrappers.rs`, static case).
fn class_method(c_method: &str) -> String {
    let raw = snake(c_method);
    let name = if raw == "create" {
        "new".to_string()
    } else if let Some(rest) = raw.strip_prefix("create_") {
        rest.to_string()
    } else {
        raw.clone()
    };
    if RESERVED_METHODS.contains(&name.as_str()) || name.starts_with("__") {
        format!("{raw}_")
    } else {
        name
    }
}

fn field_name(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

/// The Crystal type of a Vec element (`String` is a Crystal `String`).
fn elem_type(elem: &str) -> String {
    match elem {
        "String" => "::String".to_string(),
        "u8" => "::UInt8".to_string(),
        "u16" => "::UInt16".to_string(),
        "u32" => "::UInt32".to_string(),
        "u64" => "::UInt64".to_string(),
        "i8" => "::Int8".to_string(),
        "i16" => "::Int16".to_string(),
        "i32" => "::Int32".to_string(),
        "i64" => "::Int64".to_string(),
        "f32" => "::Float32".to_string(),
        "f64" => "::Float64".to_string(),
        _ => format!("Azul::{elem}"),
    }
}

fn apply(f: String, args: Vec<Doc>, broken: bool) -> Doc {
    if args.is_empty() {
        Doc::text(f)
    } else {
        Doc::call(f, args, broken)
    }
}

/// The raw lib struct of a struct literal (a struct nested in a struct).
fn lib_struct(s: &Crystal, ty: &str, fields: &[(String, Expr)], broken: bool) -> Doc {
    let fields: Vec<Doc> = fields
        .iter()
        .map(|(k, v)| {
            Doc::cat(vec![
                Doc::text(format!("{}: ", field_name(k))),
                s.field_value(v, expr_doc(s, v)),
            ])
        })
        .collect();
    Doc::call(format!("LibAzul::Az{ty}.new"), fields, broken)
}

impl ExprSyntax for Crystal {
    fn int(&self, value: i128, ty: Prim) -> String {
        let suffix = match ty {
            Prim::U8 => "u8",
            Prim::U16 => "u16",
            Prim::U32 => "u32",
            Prim::U64 | Prim::Usize => "u64",
            Prim::I8 => "i8",
            Prim::I16 => "i16",
            Prim::I32 => "i32",
            Prim::I64 | Prim::Isize => "i64",
            Prim::F32 => "f32",
            Prim::F64 => "f64",
            Prim::Bool => return String::from(if value != 0 { "true" } else { "false" }),
        };
        format!("{value}_{suffix}")
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let t = if ty == Prim::F64 { "Float64" } else { "Float32" };
        match text {
            "nan" => format!("{t}::NAN"),
            "inf" => format!("{t}::INFINITY"),
            "-inf" => format!("-{t}::INFINITY"),
            _ => format!("{text}_{}", if ty == Prim::F64 { "f64" } else { "f32" }),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("\"{}\"", escape_quoted(s, &['#'], &unicode_braced)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        apply(
            format!("Azul::{class}.{}", class_method(&snake_to_lower_camel(method))),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Azul::{ty}::{variant}")),
            EnumShape::Tagged => apply(
                format!("Azul::{ty}.{}", class_method(&variant_ctor_method(variant))),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                apply(format!("Azul::{ty}::{variant}.new"), args, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields: Vec<Doc> = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{}: ", field_name(&k))), v]))
            .collect();
        Doc::cat(vec![
            Doc::text(format!("Azul::{ty}.__own(")),
            Doc::call(format!("LibAzul::Az{ty}.new"), fields, broken),
            Doc::text(")"),
        ])
    }

    fn vec(&self, _ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        let of = format!(" of {}", elem_type(elem));
        if items.is_empty() {
            return Doc::text(format!("[]{of}"));
        }
        Doc::cat(vec![
            Doc::list("[", items, ", ", "]", false, broken, true),
            Doc::text(of),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!(
            "raise(\"not expressible: {}\")",
            escape_quoted(what, &['#'], &unicode_braced)
        ))
    }

    fn field_value(&self, field: &Expr, value: Doc) -> Doc {
        match field {
            Expr::Call { .. }
            | Expr::Variant {
                shape: EnumShape::Tagged | EnumShape::TaggedShadowed | EnumShape::Generic { .. },
                ..
            } => Doc::cat(vec![value, Doc::text(".__take")]),
            Expr::Struct { ty, fields } => lib_struct(self, ty, fields, is_tall(self, field)),
            Expr::Vec { ty, .. } => Doc::call(format!("Azul::Conv.in_{ty}"), vec![value], false),
            Expr::Str(_) => Doc::call("Azul::Native.az_string", vec![value], false),
            _ => value,
        }
    }
}

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Crystal, item) {
        out.push_str(&format!("  # {line}\n"));
    }
    let name = item.name.snake();
    if let Some(list) =
        native_list(&Crystal, &item.value, "[", "] of Azul::CssPropertyWithConditions")
    {
        out.push_str(&format!(
            "  def self.{name} : Array(Azul::CssPropertyWithConditions)\n    {}\n  end\n",
            render(&list, "  ", 2)
        ));
        return out;
    }
    match item_doc(&Crystal, item) {
        Ok(doc) => out.push_str(&format!(
            "  def self.{name} : Azul::{}\n    {}\n  end\n",
            item.ty,
            render(&doc, "  ", 2)
        )),
        Err(reason) => out.push_str(&format!(
            "  # {name}: not expressible with the Crystal bindings: {reason}\n"
        )),
    }
    out
}

impl CodegenBackend for Crystal {
    fn lang(&self) -> &'static str {
        "crystal"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["cr"]
    }

    fn display_name(&self) -> &'static str {
        "Crystal"
    }

    fn extension(&self) -> &'static str {
        "cr"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "# Generated by azul-css codegen (Crystal). Do not edit by hand.\nrequire \
             \"azul\"\n\nmodule AzulStyles\n",
        );
        for (i, item) in m.items.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&item_fn(item));
        }
        out.push_str("end\n");
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "# Copy target/codegen/crystal to ./azul and libazul here, then:\n#   shards install \
             && crystal run main.cr --link-flags=-L.\nrequire \"./styles\"\n\n",
        );
        for item in &m.items {
            if item_doc(&Crystal, item).is_err() {
                continue;
            }
            let name = item.name.snake();
            main.push_str(&format!(
                "{name} = AzulStyles.{name}\nputs \"{name}: #{{{name}.size}} properties\"\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "shard.yml".to_string(),
                contents: SHARD_YML.to_string(),
            },
            GeneratedFile {
                path: "styles.cr".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.cr".to_string(),
                contents: main,
            },
        ]
    }
}

const SHARD_YML: &str = "name: azul_styles
version: 0.1.0

dependencies:
  azul:
    path: ./azul

targets:
  azul_styles:
    main: main.cr
";
